UNION ALL SELECT 'CNT', 'PLNN', 'NTRLCDGO,PJRQCDGO,PLNNCDGO,PLNNCDPD,PLNNCNTA,PLNNESTD,PLNNFCDS,PLNNFCHA,PLNNNMBR,PLNNNVLL,PLNNTPOO' FROM DUAL
UNION ALL SELECT 'CNT', 'PLNS', 'PJRQCDGO,PLNSCDAL,PLNSCDGO,PLNSESTD,PLNSFCDS,PLNSNMBR,PLNSOBSR,PLNSSSTM' FROM DUAL
UNION ALL SELECT 'CNT', 'PLNT', 'PJRQCDGO,PLNTCDAL,PLNTCDGO,PLNTESTD,PLNTFCDS,PLNTNMBR,PLNTOBSR,PLNTSSTM' FROM DUAL
UNION ALL SELECT 'CNT', 'PRDO', 'PJRQCDGO,PRDOANNN,PRDOCDGO,PRDOCRRE,PRDODMCR,PRDODSMY,PRDOESTD,PRDOFNN,PRDOINCO,PRDOMSSS,PRDOMYCR,PRDOMYRZ,PRDONMBR' FROM DUAL
UNION ALL SELECT 'CNT', 'RCNC', 'PLNNCDGO,RCNCCDGO,RCNCDBEE,RCNCHBRR,RCNCNMBR,RCNCNMRO,RCNCSCNC,RCNCSLAC,RCNCSLAN' FROM DUAL
UNION ALL SELECT 'CNT', 'RDTC', 'CNCSCDGO,CNCSNMBR,CNCSNMRO,RCNCCDGO,RDTCCDGO,RDTCDBEE,RDTCHBRR' FROM DUAL
UNION ALL SELECT 'CNT', 'RPRT', 'PJRQCDGO,RPRTALTR,RPRTCDGO,RPRTESTD,RPRTNMBR' FROM DUAL
UNION ALL SELECT 'CNT', 'SDAS', 'DTASCDGO,SDASBSDP,SDASCDAC,SDASCDGO,SDASCSAD,SDASCTDP,SDASCTGR,SDASDPAC,SDASESTF,SDASFACT,SDASFCAD,SDASMJCP,SDASNMBR,SDASOBSR,SDASPRDP,SDASRSPN,SDASTIPO,SDASUBES,SDASUBGN,SDASVLNL,SDASVLRS,SDASVRMS,SDASVTMS' FROM DUAL
UNION ALL SELECT 'CNT', 'SLDS', 'PJRQCDGO,PLNNCDGO,SLDSCDGO,SLDSFCHN,SLDSSTDO,SLDSVLRR' FROM DUAL
),
COLS AS (
    SELECT E.OWNER_ESP,
           E.TABLA_ESP,
           TRIM(REGEXP_SUBSTR(E.COLS, '[^,]+', 1, L.LVL)) AS COLUMNA_ESP
    FROM   ESPERADO E
           CROSS JOIN (SELECT LEVEL AS LVL FROM DUAL CONNECT BY LEVEL <= 60) L
    WHERE  REGEXP_SUBSTR(E.COLS, '[^,]+', 1, L.LVL) IS NOT NULL
)
-- ============================================================================
-- CONSULTA A - Tablas mapeadas por una entidad que NO existen en la base.
-- Esperado: 0 filas.
-- ============================================================================
SELECT DISTINCT 'A. TABLA INEXISTENTE' AS HALLAZGO,
       C.OWNER_ESP || '.' || C.TABLA_ESP AS OBJETO,
       NULL AS COLUMNA
FROM   COLS C
WHERE  NOT EXISTS (SELECT 1 FROM ALL_TAB_COLUMNS A
                   WHERE A.OWNER = C.OWNER_ESP AND A.TABLE_NAME = C.TABLA_ESP)

UNION ALL

-- ============================================================================
-- CONSULTA B - Columnas mapeadas que faltan, en tablas que SI existen.
-- Cada fila es un ORA-00904 esperando el despliegue. Esperado: 0 filas.
-- ============================================================================
SELECT 'B. COLUMNA FALTANTE',
       C.OWNER_ESP || '.' || C.TABLA_ESP,
       C.COLUMNA_ESP
FROM   COLS C
WHERE  EXISTS     (SELECT 1 FROM ALL_TAB_COLUMNS A
                   WHERE A.OWNER = C.OWNER_ESP AND A.TABLE_NAME = C.TABLA_ESP)
AND    NOT EXISTS (SELECT 1 FROM ALL_TAB_COLUMNS A
                   WHERE A.OWNER = C.OWNER_ESP AND A.TABLE_NAME = C.TABLA_ESP
                   AND   A.COLUMN_NAME = C.COLUMNA_ESP)

ORDER BY 1, 2, 3;

